329	    /**
330	     * The owner's membership points, starting at zero: two points are added when an email is
331	     * on file, one more when the owner is unique (namesake count of zero), two more for a
332	     * household of three or more, and three more when the owner has accrued more than a fiscal
333	     * year of tenure (see {@link Tenure}). Derived from the owner's own fields, so it stays
334	     * consistent with them.
335	     */
336	    @Transient
337	    public Integer getMembershipPoints() {
338	        int points = 0;
339	        boolean hasEmail = this.email != null && !this.email.isEmpty();
340	        if (hasEmail) {
341	            points += 2;
342	        }
343	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
344	        if (unique) {
345	            points += 1;
346	        }
347	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
348	        if (largeHousehold) {
349	            points += 2;
350	        }
351	        boolean tenured = this.registrationDate != null
352	            && Tenure.qualifiesForTopLevel(this.registrationDate, LocalDate.now());
353	        if (tenured) {
354	            points += 3;
355	        }
356	        return points;
357	    }
