370	     * The owner's locality: the canonical region, taken as the region segment of the
371	     * customer code (formatted {@code '<REGION>-<HASH8>'}), so the locality stays
372	     * consistent with the owner's identity. When no customer code has been assigned yet
373	     * it falls back to resolving the region directly from the postcode and city (see
374	     * {@link RegionResolver}), the same rule the customer code itself is built from.
375	     */
376	    @Transient
377	    public String getLocality() {
378	        if (this.customerCode != null) {
379	            int separator = this.customerCode.indexOf('-');
380	            if (separator > 0) {
381	                return this.customerCode.substring(0, separator);
382	            }
383	        }
384	        return RegionResolver.regionFor(this.postcode, this.city);
385	    }
