408	    /**
409	     * The owner's telephone formatted for human display: the stored E.164 number
410	     * rendered as its country calling code, a space and the national digits grouped
411	     * in threes (e.g. {@code "+61 412 345 678"}). The raw {@link #getTelephone()}
412	     * stays in E.164 form. Derived from the owner's own telephone, so it stays
413	     * consistent with it. See {@link TelephoneFormatter}.
414	     */
415	    @Transient
416	    public String getTelephoneDisplay() {
