420	    /**
421	     * The owner's identity key: the single derived value used to detect duplicate owners,
422	     * formed as {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
423	     * Two owners are duplicates only when their whole identity keys are equal, so members
424	     * of one household (sharing a household id) but with different telephones stay distinct.
425	     * Derived from the owner's own fields, so it stays consistent with them.
426	     */
427	    @Transient
428	    public String getIdentityKey() {
429	        String telephonePart = this.telephone == null ? "" : this.telephone;
430	        String emailPart = this.email == null ? "" : this.email;
431	        String householdPart = this.householdId == null ? "" : this.householdId;
432	        return telephonePart + "|" + emailPart + "|" + householdPart;
433	    }
