435	    /**
436	     * The owner's age band relative to their registration date: {@code "MINOR"} when
437	     * under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or older.
438	     * Derived from the owner's own birth and registration dates, so it stays consistent
439	     * with them; null until a birth date is on file. See {@link AgeBand}.
440	     */
441	    @Transient
442	    public String getAgeBand() {
443	        if (this.birthDate == null || this.registrationDate == null) {
444	            return null;
445	        }
446	        return AgeBand.asOf(this.birthDate, this.registrationDate).name();
447	    }
