18	/**
19	 * The mapping from an owner's membership points to their membership level. Owns the
20	 * level boundaries so they live in one place rather than being scattered across callers:
21	 * 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
22	 */
23	public final class MembershipLevel {
24	
25	    private MembershipLevel() {
26	    }
27	
28	    /**
29	     * The membership level (1 to 4) earned by the given number of membership points.
30	     */
31	    public static int forPoints(int points) {
32	        if (points <= 1) {
33	            return 1;
34	        }
35	        if (points <= 3) {
36	            return 2;
37	        }
38	        if (points <= 5) {
39	            return 3;
40	        }
41	        return 4;
42	    }
43	}
