273	    /**
274	     * The deterministic, shared household id this owner maps to, derived from its last
275	     * name and postcode so that owners sharing both belong to the same household.
276	     */
277	    private String householdIdFor(Owner owner) {
278	        return householdIdGenerator.generate(owner.getLastName(), owner.getPostcode());
279	    }
